from lib import *
S = SS('j292')
steps = [
    step("japicmp 0.23.1 比较自己写的 lib v1 与 v2 两个 jar(14 个变更场景),再让针对 v1 编译的旧 client 在 v2 上真实运行、并用 javac 针对 v2 重新编译。二进制不兼容的 10 个(删除方法、int ret() 改成 long ret()、static 改成实例方法、public 改成 protected、Object get() 改成 String get()、add(int,int) 改成 add(int,long)、枚举常量被删、类改成 final、类改成 abstract、父类方法改成 final)旧 client 全都抛出 NoSuchMethodError / IncompatibleClassChangeError / IllegalAccessError / NoSuchFieldError / InstantiationError;thr() 新增 throws Exception 与 Child.m() 上移到父类:旧 client 照常运行(前者源码不兼容,后者两者都兼容);接口 Svc 新增抽象方法 b():japicmp 报告二进制兼容,但旧 client 的实现类在 v2 上抛 AbstractMethodError。汇总:二进制预测与运行一致 13 / 14,源码预测与 javac 一致 12 / 14(add(int,int) 改成 add(int,long) 与 Object get() 改成 String get() 都被报告为源码不兼容,但 client 源码重新编译通过)。", t=tl(S(1)), done=lidx(S(1), 'S01 add', 'S02 删除', 'S03 int ret', 'S04 static', 'S05 public', 'S07 Object get', 'S09 class Fin', 'S10 删除枚举', 'S14 class Abs', 'S15 父类方法'), mark=lidx(S(1), 'S06 thr', 'S08 接口', 'S13 Child', 'S17 对照', '汇总'), b=bars([['二进制预测与运行一致', 13, '13 / 14'], ['源码预测与 javac 一致', 12, '12 / 14'], ['二进制不兼容', 10, '10 个'], ['二进制兼容但源码不兼容', 2, '2 个']], 14, done=[0, 1, 2, 3]), kv=KV([['S08 接口新增抽象方法', 'japicmp:二进制兼容;实际:AbstractMethodError'], ['S01 / S07', 'japicmp:源码不兼容;实际:javac 重新编译通过'], ['S06 新增 throws', '二进制兼容、旧 client 照常运行,源码不兼容'], ['S13 方法上移到父类', '二进制与源码都兼容']], ['S08 接口新增抽象方法'])),
    step("japicmp 看不到的变化:枚举 Order 的常量顺序由 A,B,C 改成 C,A,B,日志里 Order 与 K 都是 UNCHANGED,二进制与源码都兼容,但 client 的 Order.values()[1].name() 在 v1 返回 B,在 v2 返回 A,没有任何报错;常量 K.MAX 由 10 改成 20:旧 client 在 v2 上仍然返回 10(编译时被内联进了 client 的 class 文件),针对 v2 重新编译后才返回 20,japicmp 同样没有变更记录。这两类变化只有跑测试或重新编译才能发现。", t=tl(S(2)), done=lidx(S(2), 'S11 枚举 Order'), mark=lidx(S(2), 'S12 常量 K.MAX', '日志里 K 与 Order'), kv=KV([['Order 顺序 A,B,C → C,A,B', 'values()[1]:B → A,没有报错也没有变更记录'], ['K.MAX 10 → 20', '旧 client 在 v2 上仍是 10,重新编译后是 20']], ['Order 顺序 A,B,C → C,A,B'])),
    step("真实库 commons-lang3 3.12.0 → 3.18.0:japicmp 报告共 272 个类(166 个 UNCHANGED、49 个 NEW、57 个 MODIFIED),二进制不兼容的类 0 个、变更 0 条;源码不兼容的类 10 个、变更 38 条,类型主要是 METHOD_PARAMETER_GENERICS_CHANGED × 17、CLASS_GENERIC_TEMPLATE_CHANGED × 8、METHOD_RETURN_TYPE_GENERICS_CHANGED × 7,例子有 DiffBuilder.append、ExceptionUtils.rethrow、ObjectUtils.toString。旧 jar 仍能直接链接,但用新版本重新编译的源码可能要改。", t=tl(S(3)), done=lidx(S(3), '类共 272 个'), mark=lidx(S(3), '源码不兼容变更的类型', '源码不兼容的例子'), b=bars([['UNCHANGED', 166, '166'], ['NEW', 49, '49'], ['MODIFIED', 57, '57'], ['二进制不兼容的类', 0, '0'], ['源码不兼容的类', 10, '10']], 166, done=[0, 1, 2, 3, 4]), kv=KV([['类', '272 个:166 UNCHANGED / 49 NEW / 57 MODIFIED'], ['二进制不兼容', '0 个类、0 条'], ['源码不兼容', '10 个类、38 条(主要是泛型变化)']], ['源码不兼容'])),
    step("把检查接入构建:--error-on-binary-incompatibility、--error-on-source-incompatibility、--error-on-modifications 的退出码。v1 → v3(只新增了一个 public 方法):0 / 0 / 1;v1 → v4(只给 thr() 新增 throws Exception):0 / 1 / 1;v1 → v2:1 / 1 / 1,stderr 的最后一行列出所有不兼容项(lib.Abs:CLASS_NOW_ABSTRACT、lib.Api.add(int,int):METHOD_REMOVED……)。--semantic-versioning 建议的版本号变化:commons-lang3 3.12.0 → 3.18.0 是 0.1.0,v1 → v3(只新增方法)是 0.0.1,v1 → v4 是 0.1.0,v1 → v2 是 1.0.0,没有变化也是 0.0.1。只开二进制开关会放过 v4 那样的源码不兼容。", t=tl(S(4)), done=lidx(S(4), 'v1 → v3(只新增了一个', 'v1 → v4(只给'), mark=lidx(S(4), 'v1 → v2(多种破坏性变更):binary', '--semantic-versioning', '加 -b'), kv=KV([['v1 → v3(只新增方法)', 'binary rc=0、source rc=0、modifications rc=1'], ['v1 → v4(只新增 throws)', 'binary rc=0、source rc=1'], ['v1 → v2', '三个开关都是 rc=1'], ['--semantic-versioning', 'v3 0.0.1、v4 0.1.0、v2 1.0.0']], ['v1 → v4(只新增 throws)'])),
]
